import React, { useState } from 'react';
import './App.css';
import WorkerAuth from './pages/Worke';
import WorkerDashboard from './pages/WorkerDashboard';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // This function will be passed to the Login button
  const handleLogin = () => {
    setIsAuthenticated(true);
  };

  return (
    <div className="App">
      {!isAuthenticated ? (
        <WorkerAuth onLogin={handleLogin} />
      ) : (
        <WorkerDashboard />
      )}
    </div>
  );
}

export default App; // THIS IS THE LINE YOU WERE MISSING
